      placement: ['settings'],
      fields: [],
      async run({ claims }) {
        return {
          type: 'message',
          title: 'Connector is working',
          text: `Connected and verified for ${claims.owner_name || claims.sub}. Connector version ${CONNECTOR_VERSION}.`,
        };
      },
    },
  ],
};

